def find_indices_sorted(collection, item):
    first_index, last_index = -1, -1

    start, end = 0, len(collection) - 1
    while start <= end:
        mid = (start + end) // 2
        if item < collection[mid]:
            end = mid - 1
        elif item > collection[mid]:
            start = mid + 1
        else:
            first_index = mid
            end = mid - 1
    if first_index == -1:
        return (-1, -1)
    start = first_index
    end = len(collection) - 1
    while start <= end:
