def flatten_dictionary(d):
    def items():
        for key, value in d.items():
            if isinstance(value, dict):
                for subkey, subvalue in flatten_dictionary(value).items():
                    yield key + '.' + subkey, subvalue
            else:
                yield key, value
    return dict(items())

