class Cache:
    def __init__(self, max_size):
        self.max_size = max_size
        self.cache = []

    def get(self, key):
        for index, (k, v) in enumerate(self.cache):
            if k == key:
                self.cache.append(self.cache.pop(index))
                return v
        return None

    def set(self, key, value):
        for index, (k, v) in enumerate(self.cache):
            if k == key:
                self.cache[index] = (k, value)
                self.cache.append(self.cache.pop(index))
                return
        self.cache.append((key, value))
        if len(self.cache) > self.max_size:
            self.cache.pop(0)

def memoize(max_size):
    def decorator(f):
        cache = Cache(max_size)
        def wrapper(*args, **kwargs):
            key = tuple(args) + tuple(kwargs.items())
            value = cache.get(key)
            if value is not None:
                return value
            value = f(*args, **kwargs)
            cache.set(key, value)
            return value
        return wrapper
    return decorator

