def binary_search(nums, target, start, end):
    if start > end:  # Search space is empty
        return -1

    mid = (start + end) // 2  # Calculate mid index

    if target == nums[mid]:  # Target found
        return mid

    if target > nums[mid]:  # Target is in upper half
