import numpy as np

def is_win(board: np.ndarray, player: str) -> bool:
    """
    Checks if the player has won the game of Tic-Tac-Toe.

    Args:
        board (np.ndarray): A 2D numpy array representing the game board (3x3).
        player (str): A string representing the player whose turn it is.

    Returns:
        bool: True if the player has won the game, False otherwise.
    """
    for row in board:
        if np.all(row == player):
            return True
    for col_idx in range(board.shape[1]):
        col = board[:, col_idx]
        if np.all(col == player):
            return True
    diagonals = [np.diag(board), np.diag(np.flipud(board))]
    for diagonal in diagonals:
        if np.all(diagonal == player):
            return True

    return False

