def knapsack(items, max_capacity):
    def value_to_weight_ratio(item):
        return item[0] / item[1]
    items.sort(key=value_to_weight_ratio, reverse=True)

    total_value = 0
    remaining_capacity = max_capacity

    for item in items:
        if item[1] <= remaining_capacity:
            total_value += item[0]
            remaining_capacity -= item[1]
        else:
            fraction = remaining_capacity / item[1]
            total_value += item[0] * fraction
            remaining_capacity = 0
        if remaining_capacity == 0:
            break

    return total_value

