def lookup_collection(input: str, collection: object) -> object:
    tokens = input.split(".")
    if not tokens:
        return None
    next_token = tokens[0]
    if isinstance(collection, dict):
        if next_token in collection:
            if len(tokens) == 1:
                return collection[next_token]
            return lookup_collection(".".join(tokens[1:]), collection[next_token])
        return None
    if isinstance(collection, list):
        for item in collection:
            if isinstance(item, dict):
                if len(tokens) == 1 and next_token in item:
                    return item
                result = lookup_collection(".".join(tokens[1:]), item)
                if result is not None:
                    return result
        return None
    return None

