def flatten_mapping(nested_dict: dict) -> dict:
    """
    Flattens a nested dictionary by recursively traversing it and
    building the new dictionary as we go.
    """
    new_dict = {}

    def traverse(dict_to_flatten: dict, path: str):
        """
        Recursively traverses the nested dictionary and builds the new
        dictionary as it goes.
        """
        for key, value in dict_to_flatten.items():
            if isinstance(value, dict):
                traverse(value, path + key + '.')
            elif isinstance(value, list):
                new_dict[path + key] = value
            else:
                raise TypeError('Invalid value type encountered')

    traverse(nested_dict, '')
    return new_dict

