def binary_search(array, target):
    if not array:
        raise ValueError('Array cannot be empty')
    if not isinstance(target, (int, float)):
        raise TypeError('Target must be a number')
    start = 0
    end = len(array) - 1
    def recursive_search(array, target, start, end):
        if start > end or start >= len(array) or end < 0:
            return -1
        middle = (start + end) // 2
        if target == array[middle]:
            return middle
        elif target < array[middle]:
            return recursive_search(array, target, start, middle - 1)
        else:
            return recursive_search(array, target, middle + 1, end)

    return recursive_search(array, target, start, end)

