def get_delta(old_data: dict, new_data: dict) -> dict:
    """
    Calculates the difference between two dictionaries `old_data` and `new_data`. The output
    should be a new dictionary with all keys from both input dictionaries and the corresponding
    values being the delta between the old and new values.
    """
    output = {}
    for key in old_data:
        if key in new_data:  # If the key exists in both dictionaries
            output[key] = new_data[key] - old_data[key]
        else:  # If the key exists in only `old_data`
