        return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)
    elif (0 <= x1 < width) and (0 <= y1 < height) and ((x2 == 0) or (x2 == width) or (y2 == 0) or (y2 == height)):
        if x2 == 0:
