        return math.sqrt(dx**2 + dy**2)
    elif ((x1 == 0) or (x1 == width) or (y1 == 0) or (y1 == height)) and ((x2 == 0) or (x2 == width) or (y2 == 0) or (y2 == height)):
        if x1 == 0:
