import json

def parse_json_object(json_object: str, key: str) -> any:
    parsed_object = json.loads(json_object)
    def traverse(obj: any) -> any:
        if isinstance(obj, dict):
            if key in obj:
                return obj[key]
            for value in obj.values():
                result = traverse(value)
                if result is not None:
                    return result
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                result = traverse(item)
                if result is not None:
                    return result
        return None
