def permutations(n: int, k: int) -> List[List[int]]:
    """
    Generates all permutations of `k` integers in the range [1, n] using bitmasking.
    """
    bitmask = [False] * n

    def generate_permutations(bitmask, permutation):
        if len(permutation) == k:
            yield list(permutation)
        else:
            for i in range(n):
                if not bitmask[i]:
                    bitmask[i] = True
                    permutation.append(i + 1)
                    yield from generate_permutations(bitmask, permutation)
                    permutation.pop()
                    bitmask[i] = False

    return list(generate_permutations(bitmask, []))

