def rgb_to_hsl(rgb):
    red, green, blue = rgb
    red_norm = red / 255
    green_norm = green / 255
    blue_norm = blue / 255
    max_value = max(red_norm, green_norm, blue_norm)
    min_value = min(red_norm, green_norm, blue_norm)
    delta = max_value - min_value
    if delta == 0:
        hue = 0
    elif max_value == red_norm:
        hue = (((green_norm - blue_norm) / delta) % 6) * 60
    elif max_value == green_norm:
        hue = (((blue_norm - red_norm) / delta) + 2) * 60
    else:
        hue = (((red_norm - green_norm) / delta) + 4) * 60
    if max_value == 0:
        saturation = 0
    else:
        saturation = delta / max_value
    lightness = (max_value + min_value) / 2
    return (hue, saturation, lightness)

