def increasing_matrix(matrix: List[List[int]]) -> bool:
    """
    Checks if the numbers in the matrix are increasing in total downwards and to the right.
    Returns True if the numbers are increasing, False otherwise.
    """
    if not matrix or not all(len(row) == len(matrix[0]) for row in matrix):
        return False

    for row in matrix:
        for i in range(1, len(row)):
