def count_paths(tree, target_sum):
    if not tree:
        return 0

    # Base case: leaf node
    if not tree['left'] and not tree['right']:
        return 1 if tree['value'] == target_sum else 0

    # Recursive case: sum the paths from left and right subtrees
    remaining_sum = target_sum - tree['value']
    count = 0

    if tree['left']:
        count += count_paths(tree['left'], remaining_sum)

    if tree['right']:
        count += count_paths(tree['right'], remaining_sum)

