def schedule_meetings(meetings):
    if not meetings:
        return 0

    # Sort meetings by their end times
    meetings.sort(key=lambda x: x[1])

    # Keep track of the end time of the last meeting scheduled in each room
    rooms = []

    for start, end in meetings:
        # Try to schedule the meeting in an existing room
        placed = False
        for i in range(len(rooms)):
            if rooms[i] <= start:  # Room is free
                rooms[i] = end  # Update room's end time
                placed = True
                break

        # If no room was available, create a new room
        if not placed:
            rooms.append(end)

    return len(rooms)

