def level_order_traversal(root):
    if not root:
        return []
    result = []
    queue = [root]
    while queue:
        level_size = len(queue)
        level_values = []
        for _ in range(level_size):
            node = queue.pop(0)
            level_values.append(node['value'])
            if 'left' in node:
