def kruskal_mst(n, edges):
    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_edges = []
    edges_added = 0

    for u, v, weight in edges:
        if union(u, v):
            mst_edges.append((u, v, weight))
            edges_added += 1
            if edges_added == n - 1:
                return mst_edges

    return None

