    if not intervals:
        return 0

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    # Use a min heap to track the end times of machines
    import heapq
    machine_ends = []

    for start, end in intervals:
        # If the earliest ending machine is earlier than current start
        if machine_ends and machine_ends[0] <= start:
