def min_edges_to_reach_all_nodes(graph, start_node, locked_nodes=None):
    if locked_nodes is None:
        locked_nodes = set()

    # BFS to find minimum edges to reach all nodes
    visited = set()
    queue = [(start_node, 0)]  # (node, distance)
    visited.add(start_node)

    while queue:
        current_node, distance = queue.pop(0)

        # Check if we can visit the current node
        if current_node in locked_nodes:
            continue

        # For each neighbor
        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited and neighbor not in locked_nodes:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))

    # Check if we can reach all nodes
    all_nodes = set(graph.keys())
    all_nodes.add(start_node)

    if len(visited) == len(all_nodes):
        return len(visited) - 1  # Return number of edges
    else:
        return -1

