def lru_cache(max_size):
    def decorator(func):
        cache = {}
        usage_count = {}

        def wrapper(*args, **kwargs):
            key = str(args) + str(sorted(kwargs.items()))

            if key in cache:
                usage_count[key] += 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            usage_count[key] = 1

            if len(cache) > max_size:
                least_used_key = min(usage_count, key=usage_count.get)
                del cache[least_used_key]
                del usage_count[least_used_key]

            return result

        return wrapper
    return decorator

