def count_paths(graph, start, end):
    if start == end:
        return 1

    count = 0
    stack = [start]

    while stack:
        current = stack.pop()

        if current == end:
            count += 1
            continue

        if current in graph:
            for neighbor in graph[current]:
                stack.append(neighbor)

    return count

