def validate_json_structure(input_dict, schema):
    if not isinstance(input_dict, dict) or not isinstance(schema, dict):
        return False

    for field, expected_type in schema.items():
        if field not in input_dict:
            if expected_type == 'optional':
                continue
            else:
                return False

        value = input_dict[field]

        if expected_type == 'optional':
            continue

        if isinstance(expected_type, dict):
            # Handle nested objects
            if not isinstance(value, dict):
                return False
            if not validate_json_structure(value, expected_type):
                return False
        elif expected_type == 'string':
            if not isinstance(value, str):
                return False
        elif expected_type == 'number':
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                return False
        elif expected_type == 'boolean':
            if not isinstance(value, bool):
                return False
        elif expected_type == 'array':
            # Array validation - requires specific array schema
            # For this implementation, we'll allow any array
            if not isinstance(value, list):
                return False
        elif expected_type == 'optional':
            continue
        else:
            # Check if it's a simple type
            if expected_type == 'string':
                if not isinstance(value, str):
