    if not activities:
        return 0

    # Sort activities by their end times
    sorted_activities = sorted(activities, key=lambda x: x[1])

    count = 0
    last_end_time = -1

    for start, end in sorted_activities:
        # If current activity doesn't overlap with the last selected activity
        if start >= last_end_time:
            count += 1
            last_end_time = end

    return count

def days_until_future_date(current_date, target_date):
    from datetime import datetime

    current = datetime.strptime(current_date, '%Y-%m-%d')
    target = datetime.strptime(target_date, '%Y-%m-%d')

    difference = target - current
    days = difference.days

    if days > 0:
        return days
    elif days == 0:
        return 0
    else:
        return -1

