def cached_factorial(n):
    if not isinstance(n, int) or n < 0:
        return None

    if not hasattr(cached_factorial, 'cache'):
        cached_factorial.cache = {0: 1, 1: 1}

    if n in cached_factorial.cache:
        return cached_factorial.cache[n]

    result = n * cached_factorial(n - 1)
    cached_factorial.cache[n] = result
    return result


