def traffic_light_step(current_state, time_elapsed):
    transitions = {
        'RED': {'next_state': 'GREEN', 'duration': 5},
        'GREEN': {'next_state': 'YELLOW', 'duration': 3},
        'YELLOW': {'next_state': 'RED', 'duration': 2}
    }

    if current_state not in transitions:
        raise ValueError("Invalid state")

    transition = transitions[current_state]

    if time_elapsed >= transition['duration']:
        return transition['next_state'], 0
    else:
        remaining_time = transition['duration'] - time_elapsed
        return current_state, remaining_time
